const page=document.body.dataset.page||'home';
const nav=[['home','index.html','首页'],['about','about.html','关于知微'],['programs','programs.html','训练营与课程'],['content','content.html','免费干货'],['contact','contact.html','联系合作']];
const header=`<header class="site-header"><div class="nav-inner"><a class="brand" href="index.html">沈知微</a><button class="menu-toggle" aria-label="打开菜单" aria-expanded="false"><i></i><i></i><i></i></button><nav class="site-nav">${nav.map(([id,href,label])=>`<a class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} href="${href}">${label}</a>`).join('')}<a class="btn" href="program-detail.html">查看训练营</a></nav></div></header>`;
const footer=`<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><div class="brand">沈知微</div><p>帮助职场人和创作者，把想法讲清楚，把专业表达成别人愿意听的话</p></div><div><h3>认识知微</h3><a href="index.html">首页</a><a href="about.html">关于知微</a><a href="programs.html">训练营与课程</a></div><div><h3>继续学习</h3><a href="content.html">免费干货</a><a href="article.html">文章详情</a><a href="contact.html">1对1咨询</a></div><div><h3>联系合作</h3><a href="contact.html">企业内训</a><p>微信：演示账号</p><p>邮箱：演示邮箱</p></div></div><div class="footer-bottom"><span>© 2026 沈知微</span><span>虚构案例样张｜人物、业务与数据均为演示内容</span></div></div></footer>`;
document.querySelector('[data-shell="header"]')?.insertAdjacentHTML('afterbegin',header);document.querySelector('[data-shell="footer"]')?.insertAdjacentHTML('afterbegin',footer);
const toggle=document.querySelector('.menu-toggle'),menu=document.querySelector('.site-nav');toggle?.addEventListener('click',()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});
const testimonials=[
  {img:'../reference-assets/curated-20261011/testimonial-01.jpg',name:'安娜｜互联网产品经理',quote:'以前我一到跨部门汇报就紧张训练3个月后，我第1次独立主导了完整的项目提案'},
  {img:'../reference-assets/curated-20261011/testimonial-04.jpg',name:'老周｜自由职业者',quote:'我终于能在10分钟里讲清自己的价值，也因此连续拿下了3个长期客户'},
  {img:'../reference-assets/curated-20261011/testimonial-07.jpg',name:'小叶｜内容创作者',quote:'表达不再靠临场灵感，我有了一套从观点、结构到呈现都可以重复使用的方法'}
];let ti=0;function renderTestimonial(){const root=document.querySelector('[data-testimonial]');if(!root)return;const t=testimonials[ti];root.innerHTML=`<div class="avatar"><img src="${t.img}" alt="演示头像"></div><div class="eyebrow">${t.name}</div><blockquote class="quote">“${t.quote}”</blockquote>`}renderTestimonial();document.querySelector('[data-prev]')?.addEventListener('click',()=>{ti=(ti-1+testimonials.length)%testimonials.length;renderTestimonial()});document.querySelector('[data-next]')?.addEventListener('click',()=>{ti=(ti+1)%testimonials.length;renderTestimonial()});
document.querySelectorAll('form[data-static]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const note=form.querySelector('.form-note');if(note)note.textContent='这是静态模板演示正式网站可接入你的邮箱或表单服务'}));
